import java.util.Scanner;

public class C {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();

        System.out.println(calculate(a, b, l, r));
    }

    static int calculate(int a, int b, int l, int r) {
        if ((r - l + 1) > 2 * (a + b))
            return (a <= b) ? a + 1 : (2 * a - b);

        int[] pattern = new int[3 * (a + b) + 1];
        int temp = 0;

        for (int i = 1; i <= a; i++) {
            pattern[i] = i;
            temp = i;
        }

        for (int i = a + 1; i <= a + b; i++) {
            pattern[i] = temp;
        }

        for (int i = a + b + 1; i <= a + b + a; i++) {
            int count = 1;
            while (contains(pattern, count, a + b - a + 1, i - 1))
                count++;
            pattern[i] = count;
            temp = pattern[i];
        }

        for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
            pattern[i] = temp;
        }

        for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
            pattern[i] = pattern[i - (a + b)];
        }

        int[] coverage = new int[25];
        int startIndex = l % (a + b);
        if (startIndex == 0) startIndex += a + b;
        int endIndex = r - l + startIndex;
        if (endIndex < startIndex) endIndex += a + b;

        for (int i = startIndex; i <= endIndex; i++) {
            coverage[pattern[i]] = 1;
        }

        int result = 0;
        for (int i = 1; i <= 24; i++)
            result += coverage[i];

        return result;
    }

    static boolean contains(int[] array, int value, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (array[i] == value)
                return true;
        }
        return false;
    }
}
